// src/components/Dashboard.js
import React from 'react';
import { useNavigate } from 'react-router-dom';
import '../App.css';

const Dashboard = ({ user }) => {
  const navigate = useNavigate();

  return (
    <div className="container py-5 d-flex flex-column align-items-center">
      <div className="dashboard-card text-center shadow p-4">
        <h1 className="dashboard-title mb-3">Hello, {user && user.name}!</h1>
        <p className="dashboard-subtitle mb-4">Choose the type of area you want to monitor:</p>
        <div className="d-flex flex-column gap-3">
          <button
            className="btn btn-primary dashboard-btn"
            onClick={() => navigate('/prohibited-area')}
          >
            Prohibited Area
          </button>
          <button
            className="btn btn-primary dashboard-btn"
            onClick={() => navigate('/strictly-prohibited-area')}
          >
            Strictly Prohibited Area
          </button>
          <button
            className="btn btn-outline-secondary dashboard-btn mt-3"
            onClick={() => navigate('/signin')}
          >
            Back to Login
          </button>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
